-- EXUVIA-HANDOFF-1 (2026-10-28, charter pillar reach; OWNER-NO-LOOSE-ENDS-1): qnfo-memory-mcp 2.3.x connects QNFO papers and the knowledge graph to the Exuvia agent research network
-- (exuvia-two.vercel.app; exuvia.dev is an unrelated product). Everything that needs no new account is live. The one owner-only step, creating the Exuvia agent account and storing its key as the
-- worker secret EXUVIA_API_KEY, is an IDENTITY-BOUND card with a runtime probe; the follow-up work gets a doer. Also files the METRIC-UNMEASURED-1 filer fix found in agent_issues 1000629.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE agent_issues SET status = 'closed' WHERE title LIKE 'EXUVIA-ENGAGE-1:%' OR title LIKE 'METRIC-UNMEASURED-MINSAMPLE-1:%'; UPDATE human_actions SET status = 'resolved' WHERE slug = 'exuvia-register-agent'; UPDATE remediation_contracts SET status = 'retired' WHERE class = 'owner-card-exuvia-register'; UPDATE roadmap_implementation SET status = 'retired' WHERE source = 'exuvia-2026-10';

INSERT INTO human_actions (slug, title, why, default_in_effect, action, url, sev, status, source, created_at, updated_at)
SELECT 'exuvia-register-agent', 'Create the QNFO agent account on Exuvia and store its key as the worker secret EXUVIA_API_KEY',
 'IDENTITY-BOUND: creating an account on a third-party public network and minting its API key (shown once) is an act in the owner''s name that no session or loop may perform; the key then goes into the qnfo-memory-mcp secret store under the secret-lock lease. Until it exists nothing is blocked: exuvia_status, exuvia_paper_post_draft and exuvia_kg_context work without it, and exuvia_publish_paper and exuvia_feed answer "EXUVIA_API_KEY not set".',
 'No Exuvia account exists, nothing is published there, and the read and draft tools keep working.',
 'POST https://exuvia-two.vercel.app/api/v1/agents/spawn with JSON {"name": "qnfo-research", "description": "QNFO living papers and knowledge graph", "model_name": "qnfo"}; take data.api_key from the answer (shown once); take the lease POST https://qnfo-deploy-guard.q08.workers.dev/secret-lock/acquire {"worker": "qnfo-memory-mcp", "owner": "owner", "ttl_sec": 300}; run npx wrangler secret put EXUVIA_API_KEY --name qnfo-memory-mcp; release the lease. The card closes when https://qnfo-memory-mcp.q08.workers.dev/health reports exuvia_key true.',
 'https://exuvia-two.vercel.app', 'low', 'open', 'session:EXUVIA-HANDOFF-1', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = 'exuvia-register-agent');

