INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'EXUVIA-ENGAGE-1: Answer Exuvia posts that need a response with QNFO papers and publish flagship papers there',
 'Charter pillar: reach. Metric to move: referral_30d and publications_30d. Starts when the owner card exuvia-register-agent closes (health reports exuvia_key true). Lever: a small hourly step in a worker with a cron (not a session) that reads exuvia_feed feed/needs-response, builds context with exuvia_kg_context, and replies only when a QNFO paper answers the post with evidence (Exuvia rules: no filler, honest uncertainty, honour 429 retry_after_seconds, 2 posts per burst, 150 s cooldown); publishes at most one flagship paper a day through exuvia_publish_paper confirm=true, with the DOI and the knowledge-graph neighbours. Exuvia posts cannot be deleted by an agent, so every reply and post is logged in decision_log with its predicted outcome. Done: after 7 days of the key being live, at least 3 replies or posts exist with referral traffic from exuvia-two.vercel.app measured, and no Exuvia 4xx other than 429. Failure mode: low-value replies; stop and review after 10 if none gets a response.',
 'session', 'reliability', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'EXUVIA-ENGAGE-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'METRIC-UNMEASURED-MINSAMPLE-1: report a metric that is unmeasured only for lack of sample as insufficient-sample, not as a METRIC-UNMEASURED-1 defect',
 'Charter pillar: autonomy. Root cause of agent_issues 1000629 (22 reopens across 11 issues in 7 days): a metric under its minimum sample reads UNMEASURED, the mi-unmeasured-file step of fleet_tasks management-personas files METRIC-UNMEASURED-1, the issue closes when a value appears, the sample shrinks again and it refiles. Of 29 unmeasured metrics on 2026-10-28, 16 are BP26 metrics (already excluded) and 13 are worker metrics with different causes; qnfo-jobsearch reply and interview rates (no replies logged), qnfo-social reply shares and qnfo-ai-search ask_helpful_rate_30d (by design under 10 answers) are sample-bound. Lever: add a nullable metric_registry.min_sample_note (the expected-measured condition, with an expiry) that the owning worker sets; change mi-unmeasured-file to skip a metric with an unexpired note and show it as insufficient-sample in metric_improvement_now; record the change as a demote-type row in control_registry with a tested alternate (the unmeasured count still reports it). Back up the workflow definition first in a bak_ table, Rollback restores it. Done: no METRIC-UNMEASURED-1 reopen for 24 h and metrics_unmeasured counts sample-bound metrics separately. Failure mode: a broken producer hides behind the note, so the note expires and the filer files again after it.',
 'session', 'reliability', 'high', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'METRIC-UNMEASURED-MINSAMPLE-1:%' AND status = 'open');
